// props.js: the three precision instrument stations along the Straitjacket evidence bench.
// Until each prop is built and installed with install_into_project, its stand-in holds its exact footprint.
import * as THREE from 'three';

export const PROPS = {
  capture_press: {
    at: [0, 0, 0],
    turn: 0,
    size: [1.8, 1.55, 1.1],
  },
  artifact_vault: {
    at: [3.3, 0, -1.5],
    turn: -0.22,
    size: [1.6, 1.45, 1.1],
  },
  anchor_caliper: {
    at: [6.4, 0, 0.2],
    turn: -0.35,
    size: [1.8, 1.35, 1.0],
  },
};

const pascal = (s) => s.split('_').filter(Boolean).map((p) => p[0].toUpperCase() + p.slice(1)).join('');

export function standIn([w, h, d]) {
  const geo = new THREE.BoxGeometry(w, h, d);
  geo.translate(0, h / 2, 0);
  const mesh = new THREE.Mesh(geo, new THREE.MeshStandardMaterial({ color: 0x8f97a0, roughness: 0.55, metalness: 0.25 }));
  mesh.name = 'stand-in';
  const group = new THREE.Group();
  group.add(mesh);
  return group;
}

export async function loadProp(entry, renderer) {
  if (!entry.module) return standIn(entry.size);
  const mod = await entry.module();
  const load = mod['load' + pascal(entry.asset)];
  if (typeof load !== 'function') throw new Error(`${entry.asset}: its loader has no export load${pascal(entry.asset)}`);
  return load({ renderer, baseUrl: new URL(`agy3d/${entry.asset}/`, document.baseURI).href, collision: false });
}

// shots.js: the whole scene as a pure function of story time T.
// Seven chapters, one continuous architectural evidence bench, varied shot vocabulary.

export const MOVE = 0.35;
export const REST = 0.7;
export const DESIGN_ASPECT = 1.6;
export const DESIGN_FREE = 0.6;

export const SHOT = {
  wide: { fill: 0.44, elevation: 16, fov: 34, push: 0.1, orbit: 8 },
  medium: { fill: 0.62, elevation: 22, fov: 30, push: 0.12, orbit: 6 },
  close: { fill: 0.78, elevation: 28, fov: 22, push: 0.1, orbit: 5 },
  top: { fill: 0.72, elevation: 68, fov: 30, push: 0.08, orbit: 12 },
  low: { fill: 0.6, elevation: 6, fov: 40, push: 0.08, orbit: 14 },
};

export function frame({ center, radius }, type = 'medium', { azimuth = 35, aspect = 1, ...options } = {}) {
  if (!SHOT[type]) throw new Error(`frame(): no shot type "${type}" (${Object.keys(SHOT).join(', ')})`);
  const { fill, elevation, fov, push, orbit } = { ...SHOT[type], ...options };
  const t = Math.tan((fov * Math.PI) / 360);
  const d = radius / (t * Math.min(1, aspect) * fill);
  const az = (azimuth * Math.PI) / 180, el = (elevation * Math.PI) / 180;
  const pos = [
    center[0] + d * Math.cos(el) * Math.sin(az),
    center[1] + d * Math.sin(el),
    center[2] + d * Math.cos(el) * Math.cos(az),
  ];
  return { pos, target: [...center], fov, push, orbit };
}

export function around(min, max) {
  const center = min.map((v, j) => (v + max[j]) / 2);
  return { center, radius: Math.hypot(...min.map((v, j) => max[j] - v)) / 2 };
}

// World-space bounding boxes of the three stations and key layer zones (updated after prop install if bounds differ).
const PRESS = around([-0.9, 0, -0.55], [0.9, 1.55, 0.55]);
const FLOOD_ZONE = around([-3.35, 0, -0.55], [0.9, 1.4, 0.55]);
const DIGEST_ZONE = around([-1.15, 0, -0.55], [1.75, 1.55, 0.55]);
const VAULT = around([2.45, 0, -2.15], [4.15, 1.45, -0.55]);
const CALIPER = around([5.45, 0, -0.5], [7.35, 1.35, 0.9]);
const LANES = around([0.9, 0, 1.25], [5.5, 0.45, 2.95]);
const ALL_STATIONS = around([-1.1, 0, -2.15], [7.35, 1.55, 1.1]);
const INTRO_BENCH = around([-3.1, 0, -1.8], [4.2, 1.55, 0.8]);

export const SHOTS = {
  intro: {
    ...frame(INTRO_BENCH, 'wide', { azimuth: 26, elevation: 18, fill: 0.55 }),
    span: 14,
    subject: ['capture_press', 'artifact_vault'],
  },
  flood: {
    ...frame(FLOOD_ZONE, 'low', { azimuth: -46, elevation: 6, fov: 40, fill: 0.62 }),
    span: 10,
    via: { pos: [-1.8, 2.4, 4.6], target: [-1.1, 0.65, 0] },
    subject: ['log_stream', 'capture_press'],
  },
  digest: {
    ...frame(DIGEST_ZONE, 'medium', { azimuth: 38, elevation: 24, fov: 30, fill: 0.64 }),
    span: 7,
    via: { pos: [0.2, 2.6, 4.4], target: [0.3, 0.72, 0] },
    subject: ['capture_press', 'digest_output'],
  },
  retrieve: {
    ...frame(VAULT, 'close', { azimuth: -24, elevation: 26, fov: 22, fill: 0.72 }),
    span: 6,
    via: { pos: [2.1, 2.5, 2.2], target: [2.6, 0.75, -1.2] },
    subject: ['artifact_vault', 'vault_excerpts'],
  },
  anchors: {
    ...frame(CALIPER, 'medium', { azimuth: 42, elevation: 20, fov: 28, fill: 0.64 }),
    span: 6,
    via: { pos: [6.2, 2.8, 2.8], target: [5.4, 0.7, -0.3] },
    subject: ['anchor_caliper', 'anchor_spans'],
  },
  harnesses: {
    ...frame(LANES, 'top', { azimuth: 6, elevation: 66, fov: 30, fill: 0.72, orbit: 10 }),
    span: 10,
    via: { pos: [5.2, 5.2, 3.8], target: [4.2, 0.3, 1.5] },
    subject: ['host_lanes'],
  },
  start: {
    ...frame(ALL_STATIONS, 'wide', { azimuth: 16, elevation: 9, fov: 34, fill: 0.64, push: 0.08, orbit: 8 }),
    span: 15,
    via: { pos: [4.4, 3.8, 7.6], target: [3.2, 0.7, -0.4] },
    subject: ['capture_press', 'artifact_vault', 'anchor_caliper'],
  },
};

// All three stations live permanently on the calibrated bench so moves between chapters never cross empty floor.
export const SHOW = {
  capture_press: ['intro', 'flood', 'digest', 'retrieve', 'anchors', 'harnesses', 'start'],
  artifact_vault: ['intro', 'flood', 'digest', 'retrieve', 'anchors', 'harnesses',...[4979 more chars]

// layers.js: the followed evidence, shown at true scale with InstancedMesh and troika-three-text labels.
// Every value is a pure function of story time T (via site.at); no per-frame easing.
import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { Text } from 'troika-three-text';
import { PROPS } from './props.js';
import { ramp } from './shots.js';

// Exact Addressable Evidence semantic colours (straitjacket/scripts/gen_addressable_evidence_visuals.py)
const PALETTE = {
  neutral: '#9BA2AB',
  neutralDim: '#5B626B',
  surface2: '#1C2026',
  rail: '#3B424D',
  ink: '#ECEAE3',
  blue: '#6F96FF',
  amber: '#F0B429',
  red: '#FF7768',
  green: '#63D3A4',
};

const FONT_URL = new URL('fonts/jetbrains-mono.woff', document.baseURI).href;

function makeLabel(text, { size = 0.11, color = PALETTE.ink, anchorX = 'center', anchorY = 'bottom' } = {}) {
  const t = new Text();
  t.text = text;
  t.font = FONT_URL;
  t.fontSize = size;
  t.color = color;
  t.anchorX = anchorX;
  t.anchorY = anchorY;
  t.letterSpacing = 0.04;
  t.material.toneMapped = false;
  return t;
}

export function initLayers(site) {
  const at = site.at;

  // -------------------------------------------------------------------------
  // 1. LOG STREAM: 6,053 slabs (1 slab = 50 tokens of the 302,628-token log)
  //    Collapses through capture_press to 11 kept digest slabs (531 tokens) + 1 amber needle (L14,238).
  // -------------------------------------------------------------------------
  const BEFORE = 302628;
  const AFTER = 531;
  const PER = 50;
  const N = Math.round(BEFORE / PER); // 6,053
  const KEEP = Math.round(AFTER / PER); // 11
  const COLS = 24;
  const DEEP = 10;
  const ROWS = Math.ceil(N / COLS);
  const LEVELS = Math.ceil(ROWS / DEEP); // 26

  const X_START = -3.3;
  const DX = 0.092;
  const DZ = 0.064;
  const DY = 0.032;
  const Z0 = -((DEEP - 1) * DZ) / 2;
  const BASE_Y = 0.02;
  const PRESS_X = 0.0;
  const OUT_X = 1.02;

  // One InstancedMesh for all 6,053 raw slabs (single draw call)
  const slabGeo = new THREE.BoxGeometry(0.074, 0.022, 0.048);
  const slabMat = new THREE.MeshStandardMaterial({ color: '#ffffff', roughness: 0.55, metalness: 0.1 });
  const floodMesh = new THREE.InstancedMesh(slabGeo, slabMat, N);
  floodMesh.castShadow = true;
  floodMesh.receiveShadow = true;

  const cNeutral = new THREE.Color(PALETTE.neutral);
  const cDim = new THREE.Color(PALETTE.neutralDim);
  const cRed = new THREE.Color(PALETTE.red);
  const cBlue = new THREE.Color(PALETTE.blue);
  const cAmber = new THREE.Color(PALETTE.amber);
  const cGreen = new THREE.Color(PALETTE.green);
  const cTmp = new THREE.Color();

  // Assign deterministic per-instance base colour (mostly neutral; 2 loud error rows tint softly, quiet needle stands amber)
  const NEEDLE_I = Math.round(N * (14238 / 20001)); // line 14,238 in 20,001
  for (let i = 0; i < N; i++) {
    const col = i % COLS;
    const row = Math.floor(i / COLS);
    const level = Math.floor(row / DEEP);
    if (i === NEEDLE_I) {
      floodMesh.setColorAt(i, cAmber);
    } else if (level >= LEVELS - 4) {
      floodMesh.setColorAt(i, cRed);
    } else if ((col + level) % 3 === 0) {
      floodMesh.setColorAt(i, cNeutral);
    } else {
      floodMesh.setColorAt(i, cDim);
    }
  }
  floodMesh.instanceColor.needsUpdate = true;

  // Dedicated 11 kept digest slabs + 1 bright amber quiet needle slab emerging from the press output tray.
  // Drawn with RoundedBoxGeometry (12 instances total) so edges catch the key light in the digest close-up.
  const digestGroup = new THREE.Group();
  const keptGeo = new RoundedBoxGeometry(0.11, 0.032, 0.52, 2, 0.004);
  const keptMat = new THREE.MeshStandardMaterial({ color: PALETTE.blue, roughness: 0.42, metalness: 0.15 });
  const keptMesh = new THREE.InstancedMesh(keptGeo, keptMat, KEEP);
  keptMesh.castShadow = true;
  keptMesh.receiveShadow = true;
  digestGroup.add(keptMesh);

