  renderer.shadowMap.type = THREE.PCFShadowMap; // PCFSoftShadowMap was removed in r18x: it warns and falls back

  const scene = new THREE.Scene();
  const bg = new THREE.Color(css('--bg', '#0d0f12'));
  scene.background = bg;
  scene.fog = new THREE.Fog(bg, 15, 42); // the ground fades into the page colour: no horizon line, no grid to the edge

  // Light: an environment for reflections and soft fill, one key light that casts the shadow, nothing else, within the
  // budget of the skill's libraries.md: key 1.8 and environment 0.28 keep design colours accurate and mid-value metals crisp.
  function environment() {
