/* style.css: Straitjacket Addressable Evidence design system.
   Palette & rules from straitjacket/docs/VISUAL-DESIGN.md and scripts/gen_addressable_evidence_visuals.py.
   Square corners, 1px rules, semantic colour only, no gradients, no glow, no glassmorphism. */
@import "@fontsource-variable/space-grotesk";
@import "@fontsource-variable/inter";
@import "@fontsource/jetbrains-mono/400.css";
@import "@fontsource/jetbrains-mono/500.css";

:root {
  --bg: #0d0f12;
  --ground: #1c2026;
  --surface: #15181d;
  --surface2: #1c2026;
  --ink: #eceae3;
  --muted: #8d939a;
  --faint: #7d848d;
  --grid: #272c33;
  --blue: #6f96ff;
  --blue2: #263a68;
  --amber: #f0b429;
  --amber2: #58451d;
  --red: #ff7768;
  --red2: #542925;
  --green: #63d3a4;

  --panel: rgba(21, 24, 29, 0.92);
  --font-display: "Space Grotesk Variable", system-ui, -apple-system, sans-serif;
  --font-sans: "Inter Variable", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, monospace;

  /* 3D subject sits in the right 60 % of the desktop viewport, clear of the left instrument panel. */
  --frame-x: 0.2;
  --frame-y: -0.02;
  --frame-fit: 1.12;
  color-scheme: dark;
}

* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); color: var(--ink); }
body {
  font: 15px/1.55 var(--font-sans);
  overflow-x: clip;
  -webkit-font-smoothing: antialiased;
}

/* Fixed top instrument bar: data-bar tells stage.js where free vertical area begins on phones. */
.topbar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 24px;
  background: var(--surface);
  border-bottom: 1px solid var(--grid);
}

.topbar-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.wordmark {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: 0.92rem;
  letter-spacing: 0.14em;
  color: var(--ink);
  text-decoration: none;
  white-space: nowrap;
}

.ver-badge {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  color: var(--muted);
  border: 1px solid var(--grid);
  background: var(--surface2);
  padding: 2px 7px;
  white-space: nowrap;
}

.chapter-nav {
  display: flex;
  align-items: center;
  gap: 2px;
}

.chapter-nav a {
  font-family: var(--font-mono);
  font-size: 0.72rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--muted);
  padding: 6px 9px;
  border: 1px solid transparent;
  transition: color 0.18s ease, border-color 0.18s ease, background-color 0.18s ease;
}

.chapter-nav a:hover {
  color: var(--ink);
  border-color: var(--grid);
}

.chapter-nav a.is-active {
  color: var(--ink);
  background: var(--surface2);
  border-color: var(--blue);
}

.topbar-actions {
  display: flex;
  align-items: center;
}

.docs-link {
  font-family: var(--font-mono);
  font-size: 0.76rem;
  letter-spacing: 0.04em;
  text-decoration: none;
  color: var(--ink);
  border: 1px solid var(--grid);
  background: var(--surface2);
  padding: 6px 12px;
  white-space: nowrap;
  transition: border-color 0.18s ease, color 0.18s ease;
}

.docs-link:hover {
  border-color: var(--blue);
  color: var(--blue);
}

.progress-rail {
  position: absolute;
  left: 0;
  right: 0;
  bottom: -1px;
  height: 2px;
  background: transparent;
}

.progress-fill {
  height: 100%;
  width: 0%;
  background: var(--blue);
  transform-origin: left center;
}

/* 3D canvas: fixed full viewport behind the panels. */
#stage {
  position: fixed;
